{
  "items": [
    {
      "title": "Eurostat – Sport Participation and Physical Activity in Europe",
      "url_or_doi": "https://ec.europa.eu/eurostat/statistics-explained/index.php?title=Sport_participation_-_practicing_sport_and_physical_activity",
      "justification": "Official European statistics covering participation in sports, exercise, and physical activities, including Germany. Includes indicators such as exercise frequency and participation by demographic characteristics. Useful for comparing physical activity in Germany with other European countries and examining trends where multiple survey years are available."
    },
    {
      "title": "Robert Koch Institute (RKI) – German Health Update (GEDA), 2019/2020 and 2021",
      "url_or_doi": "https://www.rki.de/DE/Themen/Nichtuebertragbare-Krankheiten/Studien-und-Surveillance/Studien/GEDA/geda_gesamt.html",
      "justification": "A major population health survey conducted by Germany's Robert Koch Institute. The 2019/2020 survey includes information about recreational physical activity, cycling, and compliance with physical activity recommendations. Particularly relevant for studying exercise habits, physical inactivity, and demographic differences among German adults during the early 2020s."
    },
    {
      "title": "German Federal Statistical Office (Destatis) – Time Use Survey 2022: Sports, Hobbies, and Games",
      "url_or_doi": "https://www.destatis.de/DE/Themen/Gesellschaft-Umwelt/Einkommen-Konsum-Lebensbedingungen/Zeitverwendung/Tabellen/aktivitaeten-sport-hobbys-geschlecht-zve.html",
      "justification": "Official German statistics from the 2022 Time Use Survey. Provides information on time spent participating in sports, hobbies, and games, including differences between men and women. Useful for analyzing leisure-time activity patterns in Germany in 2022. Sports are grouped with other recreational activities in this particular table."
    },
    {
      "title": "German Time Use Survey 2022 – Public Use Microdata",
      "url_or_doi": "https://www.forschungsdatenzentrum.de/de/10-21242-63911-2022-00-00-4-1-0",
      "justification": "An anonymized microdata sample from Germany's 2022 Time Use Survey, covering daily activities among German residents. The data can support detailed statistical analysis of time allocated to sports and physical activities, with demographic characteristics. Particularly valuable for researchers seeking individual-level observations rather than published summary statistics. The linked record identifies an earlier version of the public-use dataset."
    },
    {
      "title": "Destatis GENESIS-Online – Daily Time Use by Activity, Gender, and Household Type, 2022",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/63911/table/63911-0007",
      "justification": "Official statistical table containing average daily time spent on different activities among German adults in 2022. Includes sport-related activity categories and demographic breakdowns. Useful for quantitative research on exercise-related time allocation and differences across population groups."
    },
    {
      "title": "European Institute for Gender Equality (EIGE) – Weekly Hours Spent on Health-Enhancing Physical Activities, 2022",
      "url_or_doi": "https://dgs-p.eige.europa.eu/data/view?code=eige_care_w1_leis__ggs_leis_health",
      "justification": "Directly relevant dataset measuring weekly time spent on health-enhancing recreational physical activities, including sports, jogging, and cycling. Contains observations for Germany from 2022. Provides percentages of respondents across weekly exercise-duration categories, including respondents reporting no such activities. Particularly useful for examining exercise participation and gender differences."
    },
    {
      "title": "Eurostat – German Time Use Survey 2022 Metadata and Microdata Information",
      "url_or_doi": "https://ec.europa.eu/eurostat/cache/metadata/EN/tus_20_simstu_de.htm",
      "justification": "Official Eurostat documentation for Germany's 2022 Time Use Survey. The survey collected detailed activity diaries throughout 2022, documenting how individuals allocated time to daily activities, including leisure and recreation. Useful for understanding the dataset's methodology, population coverage, reference periods, and microdata access arrangements."
    },
    {
      "title": "OECD – Time Use Database, Germany 2022",
      "url_or_doi": "https://www.oecd.org/en/data/datasets/time-use-database.html",
      "justification": "International database containing harmonized time-use statistics, including German observations from 2022. Provides information about the distribution of time among work, leisure, personal care, and other activities. Useful for comparing Germany's activity patterns with other OECD countries. Its broad leisure categories make it less suitable for isolating exercise without additional detail."
    },
    {
      "title": "German Federal Statistical Office – Time Use Survey 2022",
      "url_or_doi": "https://www.destatis.de/EN/Themes/Society-Environment/Income-Consumption-Living-Conditions/Time-Use/_node.html",
      "justification": "Official English-language entry point for Germany's 2022 Time Use Survey. Provides tables and information about daily activities among German residents aged 10 and older. Particularly useful for examining participation in recreational activities, including sports, and identifying additional statistical tables and research data access options."
    },
    {
      "title": "A Multi-Domain Physical Fitness Dataset of Central European Adults, 2026",
      "url_or_doi": "https://doi.org/10.17605/OSF.IO/EFD2M",
      "justification": "Publicly accessible research dataset containing physical fitness measurements, including muscular strength, flexibility, stability, aerobic capacity, body composition, and other performance indicators. Includes raw and processed measurements with participant metadata. Relevant to research on physical fitness during the 2020s, although its Central European geographic coverage means researchers should verify whether the sample contains German participants before using it for Germany-specific conclusions."
    },
    {
      "title": "German Federal Statistical Office – Time Use Survey 2022 Results",
      "url_or_doi": "https://www.destatis.de/DE/Themen/Gesellschaft-Umwelt/Einkommen-Konsum-Lebensbedingungen/Zeitverwendung/Ergebnisse/_inhalt.html",
      "justification": "Official German-language results portal for the 2022 Time Use Survey, based on approximately 20,000 participants from 10,000 households. Contains detailed information about daily activities and leisure-time behavior. Useful for locating statistics on sports-related activities and examining differences across demographic groups. Results were revised in 2025 using updated population data."
    }
  ]
}
